def optimize_seating(M,N,K,L,D,chatting_pairs):
    # validation
    try:
        if not isinstance(M,int) or M<1 or not isinstance(N,int) or N<1:
            return ('','')
        if not isinstance(K,int) or K<0:
            return ('','')
        if not isinstance(L,int) or L<0:
            return ('','')
        if not isinstance(D,int) or D<0:
            return ('','')
        if D!=len(chatting_pairs):
            return ('','')
        # optional: validate tuples size 4
    except Exception:
        return ('','')
    # compute counts
    h_counts=[0]*(M-1)
    v_counts=[0]*(N-1)
    for pair in chatting_pairs:
        if len(pair)!=4:
            continue
        x1,y1,x2,y2=pair
        # horizontal
        minx=min(x1,x2)
        maxx=max(x1,x2)
        if minx< maxx:  # ensures they are in different rows
            # aisle positions from minx to maxx-1
            for r in range(minx, maxx):
                if 1<=r< M:
                    h_counts[r-1] +=1
        # vertical
        miny=min(y1,y2)
        maxy=max(y1,y2)
        if miny< maxy:
            for c in range(miny, maxy):
                if 1<=c< N:
                    v_counts[c-1] +=1
    # selection
    # horizontal
    h_indices = list(range(1,M))  # 1-index
    if h_counts:
        h_indices.sort(key=lambda i: (-h_counts[i-1], i))
        selected_rows = h_indices[:K] if K>0 else []
    else:
        selected_rows=[]
    if selected_rows:
        rows_str=' '.join(map(str,sorted(selected_rows)))
    else:
        rows_str=''
    # vertical
    v_indices = list(range(1,N))
    if v_counts:
        v_indices.sort(key=lambda i: (-v_counts[i-1], i))
        selected_cols = v_indices[:L] if L>0 else []
    else:
        selected_cols=[]
    if selected_cols:
        cols_str=' '.join(map(str,sorted(selected_cols)))
    else:
        cols_str=''
    return (rows_str, cols_str)

