    from collections import deque

    MAX_STEPS = 10
    visited = {A}
    queue = deque([(A, 0)])

    try:
        while queue:
            current, step = queue.popleft()

            # If we've reached the maximum allowed steps, stop expanding this node
            if step >= MAX_STEPS:
                continue

            for src, tgt in rules:
                start = 0
